// The frozen task, marble run v2: a marble run on a desk with a material budget, two table bumps, and moving paddles
// that may watch the marble. Units are metres, seconds and kilograms. The desk top is the plane y = 0.
// Validation seeds live in val.mjs; held-out seeds are supplied by the judge on stdin and never appear here.

export const TASK = {
  name: 'desk-marble-run-v2',
  goal: 'Build a marble run on an office desk that carries a dropped marble into the cup, even when the table gets bumped twice.',
  desk: { minX: -1.0, maxX: 1.0, minZ: -0.5, maxZ: 0.5 },
  bounds: { minX: -1.1, maxX: 1.1, minY: 0.0, maxY: 1.2, minZ: -0.6, maxZ: 0.6 },
  marble: { radius: 0.025, mass: 0.05, start: [-0.85, 0.8, -0.3] },
  cup: { center: [0.8, 0, 0.3], innerRadius: 0.07, wallHeight: 0.06, wallThickness: 0.012, segments: 20 },
  duration: 12.0,      // seconds simulated per trial; success is judged at the end
  dt: 1 / 480,         // fixed physics step
  controlHz: 60,       // how often paddles see the marble and choose a new pose
  budget: {
    pieces: 8, movers: 2, minSize: 0.012, maxSize: 1.1,
    material: 0.40,    // m^2: sum over static pieces of the area of each piece's largest face
    moverMaxSize: 0.25, moverMaxSpeed: 1.0, moverMaxSpin: 6.0,
  },
};

// Deterministic PRNG (mulberry32), so a seed always gives the same trial on every machine.
export function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// One trial: where the marble is dropped, how it moves, how grippy and bouncy the run is, and two table bumps.
export function trial(seed) {
  const r = rng(seed * 7919 + 17);
  const u = (lo, hi) => lo + (hi - lo) * r();
  const bump = (t0, t1, k0, k1) => {
    const a = u(0, 2 * Math.PI), k = u(k0, k1);
    return { time: u(t0, t1), dv: [k * Math.cos(a), u(0, 0.4), k * Math.sin(a)] };
  };
  return {
    seed,
    startOffset: [u(-0.03, 0.03), 0, u(-0.03, 0.03)],
    startVelocity: [u(-0.15, 0.15), 0, u(-0.15, 0.15)],
    friction: u(0.02, 0.3),
    restitution: u(0.05, 0.45),
    bumps: [bump(1.0, 5.0, 0.4, 1.2), bump(5.0, 9.0, 0.2, 0.8)],
  };
}

export const SMOKE = [101, 102, 103, 104];

// Camera angles the explorer's critic sees (validation views). Held-out views are chosen elsewhere.
export const VAL_CAMERAS = [
  { name: 'overview', position: [1.6, 1.3, 1.6], target: [0, 0.3, 0] },
  { name: 'closeup', position: [0.35, 0.45, 0.75], target: [0.6, 0.1, 0.2] },
  { name: 'low', position: [0.0, 0.08, 1.4], target: [0, 0.15, 0] },
  { name: 'top', position: [0.0, 2.4, 0.01], target: [0, 0, 0] },
];

// Two halves, kept apart on purpose.
// describeScene: runs a model's scene code (in the judge, inside a locked-down child process) and records what it
//   asks for: static pieces, paddle sizes, and paddle path functions that stay in that process.
// buildWorld: trusted. Checks a recorded description against the budget and builds the physics (and graphics).
// The model's code never runs in the process that knows which trial is being run.
import { TASK, rng } from './task.mjs';

export class SceneError extends Error {}

const vec = (v, n, what) => {
  if (!Array.isArray(v) || v.length !== n || !v.every((x) => typeof x === 'number' && Number.isFinite(x)))
    throw new SceneError(`${what} must be an array of ${n} finite numbers`);
  return v;
};

// Source rules for scene files: one default export, no imports, no reaching outside the arguments it is given.
// The process boundary is the real barrier; this filter is a second one and gives readable errors.
const FORBIDDEN = [/^\s*import\s/m, /\bimport\s*\(/, /\brequire\b/, /\bglobalThis\b/, /\bwindow\b/, /\bdocument\b/, /\bself\b/,
  /\bprocess\b/, /\bfetch\b/, /\beval\b/, /\bFunction\b/, /\bconstructor\b/, /\bprototype\b/, /__proto__/, /\bReflect\b/,
  /\bProxy\b/, /\bDate\b/, /\bperformance\b/, /\bsetTimeout\b/, /\bsetInterval\b/, /\bWebAssembly\b/, /\bAtomics\b/];

export function checkSource(src) {
  for (const re of FORBIDDEN) if (re.test(src)) throw new SceneError(`scene source uses a forbidden construct: ${re}`);
  if (!/export\s+default\s+function/.test(src)) throw new SceneError('scene must `export default function build({ THREE, add, task })`');
}

const deepFreeze = (o) => { Object.values(o).forEach((v) => v && typeof v === 'object' && deepFreeze(v)); return Object.freeze(o); };
const num = (x) => +(+x).toFixed(6);

// Run the scene's build with a recording API. Returns plain data plus the paddle path functions.
export function describeScene({ THREE, build, keepDecor = false }) {
  const pieces = [], movers = [], paths = [], decor = [];
  const add = Object.freeze({
    box({ size, position, rotation = [0, 0, 0], color = '#b8b8b8' } = {}) {
      pieces.push({ kind: 'box', size: vec(size, 3, 'box size').map(num), position: vec(position, 3, 'box position').map(num),
        rotation: vec(rotation, 3, 'box rotation').map(num), color: String(color).slice(0, 32) });
    },
    cylinder({ radius, height, position, rotation = [0, 0, 0], color = '#b8b8b8' } = {}) {
      pieces.push({ kind: 'cylinder', size: vec([2 * radius, height, 2 * radius], 3, 'cylinder size').map(num),
        position: vec(position, 3, 'cylinder position').map(num), rotation: vec(rotation, 3, 'cylinder rotation').map(num),
        color: String(color).slice(0, 32) });
    },
    mover({ size, path, color = '#d05a3c' } = {}) {
      if (typeof path !== 'function') throw new SceneError('mover path must be a function (t, marble) => ({ position, rotation })');
      movers.push({ size: vec(size, 3, 'mover size').map(num), color: String(color).slice(0, 32) });
      paths.push(path);
    },
    decor(object3D) {
      if (!object3D || !object3D.isObject3D) throw new SceneError('decor takes a THREE.Object3D');
      if (keepDecor) decor.push(object3D);
    },
  });
  const realRandom = Math.random;
  Math.random = rng(424242);
  try { build({ THREE, add, task: deepFreeze(structuredClone(TASK)) }); }
  catch (e) { if (e instanceof SceneError) throw e; throw new SceneError(`scene build threw: ${e && e.message}`); }
  finally { Math.random = realRandom; }
  const M = TASK.marble;
  const m0 = { position: [M.start[0], M.start[1], M.start[2]], velocity: [0, 0, 0] };
  const desc = { pieces, movers: movers.map((m, i) => ({ ...m, initial: pose(paths[i], 0, m0) })) };
  return { desc, paths, decor };
}

// A paddle's pose at time t given what it sees of the marble. Runs wherever the scene code runs.
export function pose(path, t, marble) {
  let p;
  try { p = path(t, { position: [...marble.position], velocity: [...marble.velocity] }) || {}; }
  catch (e) { throw new SceneError(`mover path threw: ${e && e.message}`); }
  return { position: vec(p.position, 3, 'mover position').map(num), rotation: vec(p.rotation || [0, 0, 0], 3, 'mover rotation').map(num) };
}

// Trusted: check a description against the frozen budget. Throws SceneError with a readable reason.
export function validateDesc(desc) {
  const B = TASK.bounds, L = TASK.budget;
  const inB = (p, what) => {
    if (p[0] < B.minX || p[0] > B.maxX || p[1] < B.minY || p[1] > B.maxY || p[2] < B.minZ || p[2] > B.maxZ)
      throw new SceneError(`${what} at [${p.map((x) => x.toFixed(3))}] is outside the allowed volume`);
  };
  if (!desc || !Array.isArray(desc.pieces) || !Array.isArray(desc.movers)) throw new SceneError('malformed scene description');
  if (desc.pieces.length > L.pieces) throw new SceneError(`${desc.pieces.length} static pieces; the budget is ${L.pieces}`);
  if (desc.movers.length > L.movers) throw new SceneError(`${desc.movers.length} movers; the budget is ${L.movers}`);
  let material = 0;
  desc.pieces.forEach((p, i) => {
    if (!['box', 'cylinder'].includes(p.kind)) throw new SceneError(`piece ${i}: unknown kind`);
    vec(p.size, 3, `piece ${i} size`); vec(p.position, 3, `piece ${i} position`); vec(p.rotation, 3, `piece ${i} rotation`);
    if (p.size.some((x) => x < L.minSize || x > L.maxSize)) throw new SceneError(`piece ${i}: every side must be ${L.minSize}..${L.maxSize} m`);
    inB(p.position, `piece ${i}`);
    const s = [...p.size].sort((a, b) => b - a);
    material += s[0] * s[1];
  });
  if (material > L.material + 1e-9) throw new SceneError(`material ${material.toFixed(3)} m^2 is over the ${L.material} m^2 budget (sum of each piece's largest face)`);
  desc.movers.forEach((m, i) => {
    vec(m.size, 3, `mover ${i} size`);
    if (m.size.some((x) => x < L.minSize || x > L.moverMaxSize)) throw new SceneError(`mover ${i}: every side must be ${L.minSize}..${L.moverMaxSize} m`);
    inB(m.initial.position, `mover ${i} start`);
  });
  return { material: +material.toFixed(4) };
}

const quatOf = (THREE, rot) => new THREE.Quaternion().setFromEuler(new THREE.Euler(rot[0], rot[1], rot[2], 'XYZ'));

// Trusted: build the physics world (and meshes when graphics is on) from a validated description.
export function buildWorld({ THREE, CANNON, desc, decor = [], trial, graphics = true }) {
  const usage = validateDesc(desc);
  const world = new CANNON.World({ gravity: new CANNON.Vec3(0, -9.81, 0) });
  world.broadphase = new CANNON.SAPBroadphase(world);
  world.allowSleep = false;
  world.solver.iterations = 20;
  const marbleMat = new CANNON.Material('marble'), pieceMat = new CANNON.Material('piece');
  world.addContactMaterial(new CANNON.ContactMaterial(marbleMat, pieceMat, { friction: trial.friction, restitution: trial.restitution }));
  const root = new THREE.Group();
  const material = (color) => new THREE.MeshStandardMaterial({ color, roughness: 0.6, metalness: 0.05 });
  const place = (body, mesh, position, rotation) => {
    const q = quatOf(THREE, rotation);
    body.position.set(...position); body.quaternion.set(q.x, q.y, q.z, q.w); world.addBody(body);
    if (mesh) { mesh.position.set(...position); mesh.quaternion.copy(q); mesh.castShadow = mesh.receiveShadow = true; root.add(mesh); }
  };
  const boxBody = (s, type) => new CANNON.Body({ mass: 0, type, material: pieceMat, shape: new CANNON.Box(new CANNON.Vec3(s[0] / 2, s[1] / 2, s[2] / 2)) });

  const d = TASK.desk, deskSize = [d.maxX - d.minX, 0.04, d.maxZ - d.minZ];
  place(boxBody(deskSize, CANNON.Body.STATIC), graphics ? new THREE.Mesh(new THREE.BoxGeometry(...deskSize), material('#9a6b43')) : null, [0, -0.02, 0], [0, 0, 0]);
  const C = TASK.cup, ring = C.innerRadius + C.wallThickness / 2;
  for (let i = 0; i < C.segments; i++) {
    const a = (i / C.segments) * 2 * Math.PI, w = (2 * Math.PI * ring / C.segments) * 1.08;
    const s = [C.wallThickness, C.wallHeight, w];
    place(boxBody(s, CANNON.Body.STATIC), graphics ? new THREE.Mesh(new THREE.BoxGeometry(...s), material('#f4f1ea')) : null,
      [C.center[0] + ring * Math.cos(a), C.wallHeight / 2, C.center[2] + ring * Math.sin(a)], [0, -a, 0]);
  }
  for (const p of desc.pieces) {
    if (p.kind === 'box') {
      place(boxBody(p.size, CANNON.Body.STATIC), graphics ? new THREE.Mesh(new THREE.BoxGeometry(...p.size), material(p.color)) : null, p.position, p.rotation);
    } else {
      const r = p.size[0] / 2, h = p.size[1];
      const body = new CANNON.Body({ mass: 0, type: CANNON.Body.STATIC, material: pieceMat, shape: new CANNON.Cylinder(r, r, h, 16) });
      place(body, graphics ? new THREE.Mesh(new THREE.CylinderGeometry(r, r, h, 24), material(p.color)) : null, p.position, p.rotation);
    }
  }
  const movers = desc.movers.map((m) => {
    const body = boxBody(m.size, CANNON.Body.KINEMATIC);
    const mesh = graphics ? new THREE.Mesh(new THREE.BoxGeometry(...m.size), material(m.color)) : null;
    place(body, mesh, m.initial.position, m.initial.rotation);
    return { body, mesh };
  });
  if (graphics) decor.forEach((o) => root.add(o));

  const M = TASK.marble;
  const marble = new CANNON.Body({ mass: M.mass, shape: new CANNON.Sphere(M.radius), material: marbleMat, linearDamping: 0.01, angularDamping: 0.01 });
  marble.position.set(M.start[0] + trial.startOffset[0], M.start[1], M.start[2] + trial.startOffset[2]);
  marble.velocity.set(...trial.startVelocity);
  world.addBody(marble);
  let marbleMesh = null;
  if (graphics) {
    marbleMesh = new THREE.Mesh(new THREE.SphereGeometry(M.radius, 32, 16), new THREE.MeshStandardMaterial({ color: '#2f7fd8', roughness: 0.15, metalness: 0.3 }));
    marbleMesh.castShadow = true; root.add(marbleMesh);
  }

  // Steer each paddle toward its requested pose, no faster than the speed limits; physics moves it between ticks.
  const B = TASK.bounds, L = TASK.budget, hz = TASK.controlHz;
  const steer = (poses) => {
    movers.forEach((m, i) => {
      const p = poses[i]; if (!p) return;
      const b = m.body;
      const target = p.position.map((x, k) => Math.min([B.maxX, B.maxY, B.maxZ][k], Math.max([B.minX, B.minY, B.minZ][k], x)));
      let v = [target[0] - b.position.x, target[1] - b.position.y, target[2] - b.position.z].map((x) => x * hz);
      const sp = Math.hypot(...v); if (sp > L.moverMaxSpeed) v = v.map((x) => x * L.moverMaxSpeed / sp);
      b.velocity.set(...v);
      const q = quatOf(THREE, p.rotation);
      const cq = new THREE.Quaternion(b.quaternion.x, b.quaternion.y, b.quaternion.z, b.quaternion.w);
      const dq = q.clone().multiply(cq.clone().invert());
      if (dq.w < 0) { dq.x = -dq.x; dq.y = -dq.y; dq.z = -dq.z; dq.w = -dq.w; }
      const ang = 2 * Math.acos(Math.min(1, dq.w)), s = Math.sqrt(Math.max(1e-12, 1 - dq.w * dq.w));
      let w = ang > 1e-6 ? [dq.x / s * ang * hz, dq.y / s * ang * hz, dq.z / s * ang * hz] : [0, 0, 0];
      const ws = Math.hypot(...w); if (ws > L.moverMaxSpin) w = w.map((x) => x * L.moverMaxSpin / ws);
      b.angularVelocity.set(...w);
    });
  };
  const syncMeshes = () => movers.forEach((m) => { if (m.mesh) { m.mesh.position.copy(m.body.position); m.mesh.quaternion.copy(m.body.quaternion); } });
  return { world, root, marble, marbleMesh, movers, steer, syncMeshes, usage };
}

// Judge the end state: is the marble resting inside the cup?
export function judgeEnd(marble) {
  const C = TASK.cup;
  const r = Math.hypot(marble.position.x - C.center[0], marble.position.z - C.center[2]);
  return { success: r < C.innerRadius && marble.position.y < C.wallHeight, distToCup: r };
}

#!/usr/bin/env node
// Trusted command line for the trials:
//   node run.mjs <scene.js> --split val|smoke | --seeds 5,6,7 | --seeds-stdin  [--json out.json] [--record]
// --seeds-stdin reads a JSON array of seeds from stdin: that is how the judge passes held-out seeds, so they never
// appear in a command line or an environment the scene could read.
import { writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { SMOKE } from './task.mjs';
import { runSeeds } from './sim.mjs';
import { SceneError } from './world.mjs';

const args = process.argv.slice(2);
const opt = (name, dflt) => { const i = args.indexOf(name); return i >= 0 ? args[i + 1] : dflt; };
const file = args[0] && !args[0].startsWith('--') ? args[0] : null;
if (!file) { console.error('usage: node run.mjs <scene.js> --split val|smoke | --seeds 5,6 | --seeds-stdin [--json out.json] [--record]'); process.exit(2); }
const valFile = join(dirname(fileURLToPath(import.meta.url)), 'val.mjs');
const VAL = existsSync(valFile) ? (await import(valFile)).VAL : [];

let seeds, split;
if (args.includes('--seeds-stdin')) {
  let s = ''; for await (const c of process.stdin) s += c;
  seeds = JSON.parse(s); split = 'heldout';
} else if (opt('--seeds')) { seeds = opt('--seeds').split(',').map(Number).filter(Number.isFinite); split = 'custom'; }
else {
  split = opt('--split', 'val');
  seeds = split === 'val' ? VAL : split === 'smoke' ? SMOKE : null;
  if (!seeds || !seeds.length) { console.error(split === 'val' ? 'no validation trials in this copy of the harness' : `unknown split ${split}`); process.exit(2); }
}

const t0 = Date.now();
let out;
try {
  out = { scene: file, split, valid: true, ...(await runSeeds(file, seeds, { record: args.includes('--record') })) };
} catch (e) {
  if (!(e instanceof SceneError)) throw e;
  out = { scene: file, split, valid: false, error: e.message, passed: 0, total: seeds.length, rate: 0, results: [] };
}
out.seconds = +((Date.now() - t0) / 1000).toFixed(1);
if (opt('--json')) writeFileSync(opt('--json'), JSON.stringify(out));
if (!out.valid) { console.log(`INVALID SCENE: ${out.error}`); process.exit(1); }
console.log(`${split}: ${out.passed}/${out.total} trials ended in the cup (${out.seconds}s; ${out.pieces} pieces, ${out.movers} paddles, material ${out.material} m^2)`);
if (split !== 'heldout') for (const r of out.results) {
  console.log(`  seed ${r.seed}: ${r.success ? 'IN CUP' : r.reason}; final [${r.final}] ${r.distToCup} m from cup centre; bumps at ${r.bumpTimes.join(', ')} s`);
}

// Trusted judge side: starts the scene in a locked-down child process, gets its description, and runs trials.
// Scenes without paddles are described once (their pieces cannot react to anything); scenes with paddles get a
// fresh child per trial, so nothing carries over from one trial to the next.
import * as THREE from 'three';
import * as CANNON from 'cannon-es';
import { spawn } from 'node:child_process';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { validateDesc, SceneError } from './world.mjs';
import { runTrial } from './trialrun.mjs';

const HERE = dirname(fileURLToPath(import.meta.url));
const PERM = process.allowedNodeEnvironmentFlags.has('--permission') ? '--permission' : '--experimental-permission';
const READ = [join(HERE, 'host.mjs'), join(HERE, 'world.mjs'), join(HERE, 'task.mjs'), join(HERE, 'package.json'),
  join(HERE, 'node_modules', 'three'), join(HERE, 'node_modules', 'three', '*')];

export class ChildHost {
  constructor(sceneFile) {
    const scene = resolve(sceneFile);
    this.proc = spawn(process.execPath, [PERM, ...[...READ, scene].map((p) => `--allow-fs-read=${p}`), join(HERE, 'host.mjs'), scene],
      { env: {}, stdio: ['pipe', 'pipe', 'pipe'] });
    this.buf = ''; this.waiting = []; this.stderr = '';
    this.proc.stdout.on('data', (d) => {
      this.buf += d;
      let k;
      while ((k = this.buf.indexOf('\n')) >= 0) {
        const line = this.buf.slice(0, k); this.buf = this.buf.slice(k + 1);
        const w = this.waiting.shift();
        if (w) { clearTimeout(w.timer); try { w.ok(JSON.parse(line)); } catch { w.no(new SceneError('scene process wrote something that is not a reply')); } }
      }
    });
    this.proc.stderr.on('data', (d) => { this.stderr = (this.stderr + d).slice(-2000); });
    this.proc.on('exit', (code) => { for (const w of this.waiting.splice(0)) { clearTimeout(w.timer); w.no(new SceneError(`scene process exited (${code}): ${this.stderr.trim().split('\n').slice(-2).join(' ')}`)); } });
  }
  ask(msg, ms) {
    return new Promise((ok, no) => {
      const timer = setTimeout(() => no(new SceneError(`scene process did not answer within ${ms} ms`)), ms);
      this.waiting.push({ ok, no, timer });
      this.proc.stdin.write(JSON.stringify(msg) + '\n');
    });
  }
  async describe() {
    const r = await this.ask({ op: 'describe' }, 15000);
    if (r.error) throw new SceneError(r.error);
    return r.desc;
  }
  async tick(t, marble) {
    const r = await this.ask({ op: 'tick', t, marble }, 2000);
    if (r.error) throw new SceneError(r.error);
    return r.poses;
  }
  close() { try { this.proc.stdin.end(); this.proc.kill(); } catch { /* already gone */ } }
}

async function pool(items, n, fn) {
  const out = new Array(items.length); let next = 0;
  await Promise.all(Array.from({ length: Math.min(n, items.length) }, async () => {
    while (next < items.length) { const i = next++; out[i] = await fn(items[i], i); }
  }));
  return out;
}

export async function runSeeds(sceneFile, seeds, { record = false, concurrency = 8 } = {}) {
  const probe = new ChildHost(sceneFile);
  let desc;
  try { desc = await probe.describe(); } finally { probe.close(); }
  const usage = validateDesc(desc);
  const results = await pool(seeds, concurrency, async (seed) => {
    if (!desc.movers.length) {
      const { result, track } = await runTrial({ THREE, CANNON, desc, seed, record });
      return record ? { ...result, track } : result;
    }
    const host = new ChildHost(sceneFile);
    try {
      const fresh = await host.describe();
      const { result, track } = await runTrial({ THREE, CANNON, desc: fresh, host, seed, record });
      return record ? { ...result, track } : result;
    } finally { host.close(); }
  });
  const passed = results.filter((r) => r.success).length;
  return { passed, total: seeds.length, rate: +(passed / seeds.length).toFixed(4), material: usage.material,
    pieces: desc.pieces.length, movers: desc.movers.length, results };
}

// The trial loop, shared by the Node judge and the browser viewer so a replay is the run the judge scored.
// `host.tick(t, marble)` returns the paddles' requested poses. In the judge that is a locked-down child process;
// in the browser viewer it is the scene's own functions.
import { TASK, trial as makeTrial } from './task.mjs';
import { buildWorld, judgeEnd, SceneError } from './world.mjs';

export async function runTrial({ THREE, CANNON, desc, decor = [], host = null, seed, graphics = false, record = false, bumpsOverride = null }) {
  const tr = makeTrial(seed);
  if (bumpsOverride) tr.bumps = bumpsOverride;
  const w = buildWorld({ THREE, CANNON, desc, decor, trial: tr, graphics });
  const { world, marble } = w;
  const steps = Math.round(TASK.duration / TASK.dt);
  const every = Math.round(1 / 30 / TASK.dt), tickEvery = Math.round(1 / TASK.controlHz / TASK.dt);
  const applied = tr.bumps.map(() => false);
  const track = [];
  let fell = false, still = 0, t = 0, maxSpeed = 0, reason = null;
  const snap = () => track.push({ t: +t.toFixed(4), p: [marble.position.x, marble.position.y, marble.position.z],
    q: [marble.quaternion.x, marble.quaternion.y, marble.quaternion.z, marble.quaternion.w],
    movers: w.movers.map((m) => ({ p: [m.body.position.x, m.body.position.y, m.body.position.z],
      q: [m.body.quaternion.x, m.body.quaternion.y, m.body.quaternion.z, m.body.quaternion.w] })) });
  for (let i = 0; i < steps; i++) {
    t = i * TASK.dt;
    if (record && i % every === 0) snap();
    if (w.movers.length && i % tickEvery === 0) {
      try {
        w.steer(await host.tick(+t.toFixed(5), { position: [marble.position.x, marble.position.y, marble.position.z],
          velocity: [marble.velocity.x, marble.velocity.y, marble.velocity.z] }));
      } catch (e) {
        reason = `paddle code failed at t=${t.toFixed(2)}s: ${e && e.message}`;
        break;
      }
    }
    tr.bumps.forEach((b, k) => {
      if (!applied[k] && t >= b.time) {
        marble.velocity.x += b.dv[0]; marble.velocity.y += b.dv[1]; marble.velocity.z += b.dv[2];
        applied[k] = true;
      }
    });
    world.step(TASK.dt);
    const v = marble.velocity.length();
    maxSpeed = Math.max(maxSpeed, v);
    if (marble.position.y < -0.3) { fell = true; break; }
    // Early stop once the marble has rested for a second after the last bump (scenes without paddles only).
    still = v < 0.002 ? still + TASK.dt : 0;
    if (!w.movers.length && applied.every(Boolean) && still > 1.0) break;
  }
  w.syncMeshes();
  if (record) snap();
  const end = judgeEnd(marble);
  return {
    result: {
      seed, success: !fell && !reason && end.success, fell, reason: reason || (fell ? 'fell off the desk' : end.success ? 'in the cup' : 'missed'),
      distToCup: +end.distToCup.toFixed(4), simulatedSeconds: +t.toFixed(2),
      final: [marble.position.x, marble.position.y, marble.position.z].map((x) => +x.toFixed(4)), maxSpeed: +maxSpeed.toFixed(3),
      bumpTimes: tr.bumps.map((b) => +b.time.toFixed(2)), material: w.usage.material,
    },
    track, world: w,
  };
}

