// Let us test a simple ramp with walls from [-0.95, y0, -0.34] to [0.75, y1, 0.28]
function makeBuild(params) {
  return ({ THREE, add, task }) => {
    const { x0, y0, z0, x1, y1, z1, width, wallH, wallT, floorT, funnelPieces } = params;
    const dx = x1 - x0, dy = y1 - y0, dz = z1 - z0;
    const len = Math.hypot(dx, dy, dz);
    const hLen = Math.hypot(dx, dz);
    const yaw = -Math.atan2(dz, dx); // wait! In THREE.js, rotation around Y by ry: local +X goes to [cos(ry), 0, -sin(ry)]!
    // Wait, let us check THREE.Euler XYZ!
    const dir = new THREE.Vector3(dx, dy, dz).normalize();
    // We want local X along dir, and local Z horizontal!
    const up = new THREE.Vector3(0, 1, 0);
    const localZ = new THREE.Vector3().crossVectors(dir, up).normalize(); // Wait: X cross Y = Z -> dir cross up is in XZ plane!
    // Wait: if dir is (+x, -y, +z), dir cross (0,1,0) = (-dz, 0, dx), wait: (dx, dy, dz) x (0, 1, 0) = (-dz, 0, dx).
    // In right-handed coords, X cross Y = Z, so Y = Z cross X. Let us check: (-dz, 0, dx) cross (dx, dy, dz) = (-dx*dy, dz^2+dx^2, -dz*dy), which has +Y!
    const localY = new THREE.Vector3().crossVectors(localZ, dir).normalize();
    const m = new THREE.Matrix4().makeBasis(dir, localY, localZ);
    const e = new THREE.Euler().setFromRotationMatrix(m, "XYZ");
    const rot = [e.x, e.y, e.z];

    const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2, cz = (z0 + z1) / 2;
    const center = new THREE.Vector3(cx, cy, cz);

    // Floor
    const fPos = center.clone().addScaledVector(localY, -floorT / 2);
    add.box({ size: [len, floorT, width], position: [fPos.x, fPos.y, fPos.z], rotation: rot });

    // Left and right walls
    const wOffsetY = wallH / 2 - floorT;
    const wOffsetZ = width / 2 + wallT / 2;
    for (const s of [-1, 1]) {
      const wPos = center.clone().addScaledVector(localY, wOffsetY).addScaledVector(localZ, s * wOffsetZ);
      add.box({ size: [len, wallH, wallT], position: [wPos.x, wPos.y, wPos.z], rotation: rot });
    }

    for (const fp of (funnelPieces || [])) {
      add.box(fp);
    }
  };
}

